import {
  Box,
  Button,
  FormControl,
  MenuItem,
  Select,
  Stack,
  Switch,
  Typography,
} from "@mui/material";

import PlayArrowRoundedIcon from "@mui/icons-material/PlayArrowRounded";
import RefreshRoundedIcon from "@mui/icons-material/RefreshRounded";
import RestartAltRoundedIcon from "@mui/icons-material/RestartAltRounded";

import {
  useForecastContext,
} from "../../contexts/ForecastContext";

import {
  ForecastHorizon,
  ForecastMetric,
  ForecastScenario,
} from "../../features/forecast/types/forecast.types";

const ForecastContextBar = () => {
  const {
    horizon,
    metric,
    entityId,
    scenario,
    autoRefresh,
    lastUpdated,
    setHorizon,
    setMetric,
    setEntityId,
    setScenario,
    setAutoRefresh,
    refresh,
    reset,
  } = useForecastContext();

  const entities = [
    "entity_1",
    "entity_2",
    "entity_3",
    "entity_4",
    "entity_5",
    "entity_6",
    "entity_7",
    "entity_8",
    "entity_9",
    "entity_10",
    "entity_11",
    "entity_12",
    "entity_13",
    "entity_14",
    "entity_15",
  ];

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  return (
    <Box
      sx={{
        width: "100%",
        backgroundColor: "background.paper",
        border: "1px solid",
        borderColor: "divider",
        borderRadius: 3,
        boxSizing: "border-box",
        px: {
          xs: 2.5,
          sm: 3,
          md: 4,
        },
        py: {
          xs: 2.5,
          sm: 3,
          md: 3.5,
        },
      }}
    >
      <Stack spacing={3}>
        {/* ===================================================== */}
        {/* HEADER */}
        {/* ===================================================== */}

        <Stack
          direction={{
            xs: "column",
            md: "row",
          }}
          justifyContent="space-between"
          alignItems={{
            xs: "flex-start",
            md: "center",
          }}
          spacing={2}
        >
          <Box>
            <Typography
              variant="h4"
              sx={{
                fontWeight: 700,
                lineHeight: 1.2,
                color: "text.primary",
                mb: 0.75,
              }}
            >
              Forecast Context
            </Typography>

            <Typography
              variant="body1"
              sx={{
                color: "text.secondary",
                fontSize: "1.05rem",
              }}
            >
              Configure the forecast horizon, metric, entity and scenario.
            </Typography>
          </Box>
        </Stack>

        {/* ===================================================== */}
        {/* FILTERS */}
        {/* ===================================================== */}

        <Box
          sx={{
            display: "grid",

            gridTemplateColumns: {
              xs: "1fr",
              sm: "repeat(2, minmax(0, 1fr))",
              lg: "repeat(4, minmax(0, 1fr))",
            },

            gap: {
              xs: 2,
              md: 2.5,
            },

            width: "100%",
          }}
        >
          {/* HORIZON */}

          <FormControl fullWidth>
            <Typography
              variant="body2"
              sx={{
                color: "text.secondary",
                fontWeight: 600,
                mb: 1,
              }}
            >
              Horizon
            </Typography>

            <Select
              value={horizon}
              onChange={(event) =>
                setHorizon(
                  event.target.value as ForecastHorizon
                )
              }
              fullWidth
            >
              <MenuItem value="daily">
                Tactical (Daily - 90 Days)
              </MenuItem>

              <MenuItem value="monthly">
                Strategic (Monthly - 36 Months)
              </MenuItem>
            </Select>
          </FormControl>

          {/* METRIC */}

          <FormControl fullWidth>
            <Typography
              variant="body2"
              sx={{
                color: "text.secondary",
                fontWeight: 600,
                mb: 1,
              }}
            >
              Metric
            </Typography>

            <Select
              value={metric}
              onChange={(event) =>
                setMetric(
                  event.target.value as ForecastMetric
                )
              }
              fullWidth
            >
              <MenuItem value="burn">
                Burn Predictions
              </MenuItem>

              <MenuItem value="supply">
                Supply Predictions
              </MenuItem>

              <MenuItem value="stockpile">
                Stockpile
              </MenuItem>
            </Select>
          </FormControl>

          {/* ENTITY */}

          <FormControl fullWidth>
            <Typography
              variant="body2"
              sx={{
                color: "text.secondary",
                fontWeight: 600,
                mb: 1,
              }}
            >
              Forecast Entity
            </Typography>

            <Select
              value={entityId}
              onChange={(event) =>
                setEntityId(event.target.value)
              }
              fullWidth
            >
              {entities.map((entity) => (
                <MenuItem
                  key={entity}
                  value={entity}
                >
                  {entity}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          {/* SCENARIO */}

          <FormControl fullWidth>
            <Typography
              variant="body2"
              sx={{
                color: "text.secondary",
                fontWeight: 600,
                mb: 1,
              }}
            >
              Scenario
            </Typography>

            <Select
              value={scenario}
              onChange={(event) =>
                setScenario(
                  event.target.value as ForecastScenario
                )
              }
              fullWidth
            >
              <MenuItem value="actual">
                Actual (Baseline)
              </MenuItem>

              <MenuItem value="hotdry">
                Hot &amp; Dry
              </MenuItem>

              <MenuItem value="hotwet">
                Hot &amp; Wet
              </MenuItem>

              <MenuItem value="colddry">
                Cold &amp; Dry
              </MenuItem>

              <MenuItem value="coldwet">
                Cold &amp; Wet
              </MenuItem>
            </Select>
          </FormControl>
        </Box>

        {/* ===================================================== */}
        {/* FOOTER */}
        {/* ===================================================== */}

        <Stack
          direction={{
            xs: "column",
            md: "row",
          }}
          justifyContent="space-between"
          alignItems={{
            xs: "flex-start",
            md: "center",
          }}
          spacing={2}
          sx={{
            width: "100%",
          }}
        >
          {/* LEFT */}

          <Stack
            direction="row"
            alignItems="center"
            spacing={1}
          >
            <Typography
              variant="body2"
              sx={{
                color: "text.secondary",
                fontWeight: 500,
                whiteSpace: "nowrap",
              }}
            >
              Auto Refresh
            </Typography>

            <Switch
              checked={autoRefresh}
              onChange={(event) =>
                setAutoRefresh(
                  event.target.checked
                )
              }
              size="small"
            />

            <Typography
              variant="body2"
              sx={{
                color: "text.secondary",
                ml: 1,
                whiteSpace: "nowrap",
              }}
            >
              Updated {formatTime(lastUpdated)}
            </Typography>
          </Stack>

          {/* RIGHT */}

          <Stack
            direction="row"
            spacing={2}
          >
            <Button
              variant="outlined"
              startIcon={
                <RestartAltRoundedIcon />
              }
              onClick={reset}
              sx={{
                height: 48,
                minWidth: 130,
                px: 2.5,
                borderRadius: 2,
                textTransform: "none",
                fontWeight: 600,
              }}
            >
              Reset
            </Button>


          </Stack>
        </Stack>
      </Stack>
    </Box>
  );
};

export default ForecastContextBar;
